test('home daily context is server-built and bounded; absent scientific evidence never grants uncited model conclusions',async()=>{const f=fixture(),original=globalThis.fetch;await configured(f);const selection={newPapers:7,eligible:0};f.sql.prepare("INSERT INTO research_daily(date,source_date,cutoff,status,coverage_json,selection_json,paper_ids_json,content_hash,schema_version,prompt_version,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)").run('2026-01-02','2026-01-01','2026-01-02T00:00:00Z','incomplete',JSON.stringify({complete:false,untrackedNewPapers:3}),JSON.stringify(selection),'[]','hash','schema','prompt','2026-01-02T00:00:00Z','2026-01-02T00:00:00Z');let calls=0;globalThis.fetch=async(_url:any,init:any)=>{calls++;const body=JSON.parse(init.body),input=JSON.stringify(body.input||body.messages);assert.ok(input.includes('2026-01-02'));assert.ok(input.includes('新论文 7 篇'));assert.ok(!input.includes('CLIENT_FORGED_DAILY'));assert.ok(input.length<16000);return Response.json({output:[{type:'message',content:[{type:'output_text',text:JSON.stringify({answer:'模型捏造的科学突破',paperIds:[],analyses:[]})}]}]})};try{const r=await request(f.env,'chat',{message:'最新日报有什么',latestDaily:true,daily:{summary:'CLIENT_FORGED_DAILY'},requestId:crypto.randomUUID()});assert.equal(r.status,200);const result=await r.json();assert.equal(calls,1);assert.equal(result.dailyStatus.url,'/daily/2026-01-02');assert.ok(result.answer.includes('来源日 2026-01-01'));assert.ok(result.answer.includes('采集覆盖不完整'));assert.ok(!result.answer.includes('捏造'));assert.equal(result.toolCalls,0)}finally{globalThis.fetch=original;f.sql.close()}});
